package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import com.lianxibu.site.repository.jobs.*;
import java.time.*;
import org.junit.jupiter.api.Test;
import javax.sql.DataSource;
import org.springframework.transaction.PlatformTransactionManager;
/** Actual complete daily prepare. The source/model/settings genesis remains fictional, no additional model call. */
class ReportDispatchPermitTest {
 boolean mysql(){return false;}
 ReportDailyPreparationIntegrationTest h;ReportPreparedInputService.Prepared original;ReportDispatchPermitService permits;ReportNoUpdateProofService noUpdates;
 void setup()throws Exception{h=new ReportDailyPreparationIntegrationTest(){@Override boolean mysql(){return ReportDispatchPermitTest.this.mysql();}};h.setup();original=h.prepare();var base=h.f.data.nativeData().fixture().f();noUpdates=new ReportNoUpdateProofService(base.source,h.originals,base.writes,base.tx,Clock.systemUTC());permits=new ReportDispatchPermitService(base.source,h.originals,noUpdates,base.tx);}
 @Test void FullNativeOriginalRequestAndProgramReceiptIssueOnlySameWriterVerifiablePermit()throws Exception{setup();var value=permits.capture(original.input().ownerId());assertNotNull(value);assertEquals(original,value.prepared());assertTrue(value.originalByteSize()>original.input().snapshotJson().length());assertSame(value,h.f.rr(()->permits.verifyObserved(value)));var base=h.f.data.nativeData().fixture().f();assertSame(value,base.writes.execute(base.action("fictional-report-dispatch-permit"),k->null,a->permits.verifyInWriter(value)));assertEquals(2,base.sends);assertFalse(value.toString().contains("Fictional"));}
 @Test void NativeProgramReceiptAndOriginalRequestDamageRejectInsteadOfTrustingAParsedInput()throws Exception{setup();var value=permits.capture(original.input().ownerId());var base=h.f.data.nativeData().fixture().f();base.jdbc.update("UPDATE jobs SET operator_id='fictional-other-program' WHERE target_type='generation_prepare' AND operator_id=?",JdbcReportPreparedInputs.ACTOR);assertThrows(RuntimeException.class,()->permits.capture(original.input().ownerId()));assertThrows(RuntimeException.class,()->base.writes.execute(base.action("fictional-report-damaged-native-permit"),k->null,a->permits.verifyInWriter(value)));setup();var second=h.f.data.nativeData().fixture().f();second.jdbc.update("UPDATE jobs SET request_json='{}' WHERE root_job_id=? AND attempt_no=1",original.input().ownerId());assertThrows(RuntimeException.class,()->permits.capture(original.input().ownerId()));}
 @Test void OrdinaryNoInputOrMissingSourceNeverAuthorizesDispatchAndCurrentBodyCannotRewriteOriginal()throws Exception{setup();var value=permits.capture(original.input().ownerId());var base=h.f.data.nativeData().fixture().f();base.jdbc.update("UPDATE contents SET body_json='{}'");assertEquals(value.prepared(),permits.capture(original.input().ownerId()).prepared());var no=new ReportNoUpdateProofTest(){@Override boolean mysql(){return ReportDispatchPermitTest.this.mysql();}};no.setup();no.service.observe(no.f.f.scope);base=no.f.f.f.data.nativeData().fixture().f();var actual=new ReportDispatchPermitService(base.source,no.f.f.originals,no.service,base.tx);assertNull(actual.capture(no.f.original.input().ownerId()));assertFalse(actual.lookup(no.f.original.input().ownerId()));assertEquals(2,base.sends);}
 @Test void ForeignIssuerOrReadonlyWriterOrUnownedTransactionCannotMintPermissionAndConstructionIsCold()throws Exception{setup();var value=permits.capture(original.input().ownerId());var base=h.f.data.nativeData().fixture().f();var other=new ReportDispatchPermitService(base.source,h.originals,noUpdates,base.tx);assertThrows(RuntimeException.class,()->h.f.rr(()->other.verifyObserved(value)));assertThrows(RuntimeException.class,()->permits.verifyObserved(value));assertThrows(RuntimeException.class,()->permits.verifyInWriter(value));assertThrows(RuntimeException.class,()->h.f.rr(()->permits.verifyInWriter(value)));assertThrows(RuntimeException.class,()->h.f.rr(()->permits.capture(value.rootId())));var ds=mock(DataSource.class);var prep=mock(ReportPreparedInputService.class);var no=mock(ReportNoUpdateProofService.class);var tx=mock(PlatformTransactionManager.class);new ReportDispatchPermitService(ds,prep,no,tx);verifyNoInteractions(ds,prep,no,tx);}
}
